function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  if (typeof tw.compile !== "function") broken("tailwindcss has no compile export");
  const compiler = await tw.compile("@theme { --spacing: 0.25rem; }\n@tailwind utilities;");
  const out = compiler.build(["start", "end", "start-4"]);
  if (!/\.start-4\s*\{[^}]*inset-inline-start/.test(out)) broken("start-4 did not generate inset-inline-start: " + out);
  if (/\.(start|end)\s*\{/.test(out)) symptom("bare start and end utilities generate CSS");
  console.log("OK: bare start and end generate no CSS");
})().catch(e => broken(String((e && e.stack) || e)));

